package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.net.MalformedURLException;
import java.net.URL;
import java.util.*;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import org.jsoup.helper.StringUtil;
import org.jsoup.helper.Validate;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.jsoup.nodes.Node;
import org.jsoup.nodes.TextNode;
import org.jsoup.parser.Parser;
import org.jsoup.select.NodeTraversor;
import org.jsoup.select.NodeVisitor;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class Node_previousSibling_TriageGen0Test {

    private Node parentNode;
    private Node child1;
    private Node child2;
    private Node child3;
    private Node child4;

    @Before
    public void setUp() {
        Document doc = new Document("");
        parentNode = doc.body();

        child1 = new TextNode("child1");
        child2 = new TextNode("child2");
        child3 = new TextNode("child3");
        child4 = new TextNode("child4");

        parentNode.appendChild(child1);
        parentNode.appendChild(child2);
        parentNode.appendChild(child3);
        parentNode.appendChild(child4);

        child1.setParentNode(parentNode);
        child2.setParentNode(parentNode);
        child3.setParentNode(parentNode);
        child4.setParentNode(parentNode);
    }

    @Test
    public void testPreviousSibling_WhenHasPrevious() {
        assertEquals(child1.previousSibling(), null);
        assertEquals(child2.previousSibling(), child1);
        assertEquals(child3.previousSibling(), child2);
        assertEquals(child4.previousSibling(), child3);
    }

    @Test
    public void testPreviousSibling_WhenNoPrevious() {
        child1.remove();
        assertEquals(child2.previousSibling(), null);
        assertEquals(child3.previousSibling(), child2);
        assertEquals(child4.previousSibling(), child3);
    }

    @Test
    public void testPreviousSibling_WhenNodeIsRoot() {
        Node root = new TextNode("root");
        assertEquals(root.previousSibling(), null);
    }

    @Test
    public void testPreviousSibling_WhenParentNodeIsNull() {
        Node nodeWithoutParent = new TextNode("noParent");
        assertNull(nodeWithoutParent.previousSibling());
    }

    @Test
    public void testPreviousSibling_WhenSiblingIndexIsNegative() {
        child1.setSiblingIndex(-1);
        assertEquals(child1.previousSibling(), null);
    }

    @Test
    public void testPreviousSibling_WhenSiblingIndexIsZero() {
        child2.setSiblingIndex(0);
        assertEquals(child2.previousSibling(), null);
    }
}
